#!/usr/bin/env python3
"""Compute the reference values for CSX-059_Q1."""

from __future__ import annotations

import json
import re
from html.parser import HTMLParser
from pathlib import Path


TASK_ID = "CSX-059_Q1"
EVENT_ID = "CSX-059"
TARGET_FAMILY = "rainfall_threshold_ledger"
REPORT_REL_PATH = "data/event_reports/event_reports_001_Locked_package_evidence_report.html"


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
        self.skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"script", "style", "noscript"}:
            self.skip_depth += 1

    def handle_endtag(self, tag: str) -> None:
        if tag in {"script", "style", "noscript"} and self.skip_depth:
            self.skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if not self.skip_depth and data.strip():
            self.parts.append(data.strip())


def package_root() -> Path:
    task_dir = Path(__file__).resolve().parent
    repo_root = task_dir.parents[2]
    return repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def html_text(path: Path) -> str:
    parser = TextExtractor()
    parser.feed(path.read_text(encoding="utf-8", errors="replace"))
    return re.sub(r"\s+", " ", " ".join(parser.parts))


def first_number(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1))


def main() -> None:
    report = html_text(package_root() / REPORT_REL_PATH)

    record_hour_inches = first_number(r"wettest hour on record\s*--\s*([0-9.]+)", report)
    regional_floor_inches = first_number(
        r"amounts in the northern Mid-Atlantic States peaked just above ([0-9.]+)",
        report,
    )

    record_hour_mm_exact = record_hour_inches * 25.4
    regional_floor_mm = regional_floor_inches * 25.4
    ratio = record_hour_inches / regional_floor_inches

    record_hour_mm = round(record_hour_mm_exact, 1)
    regional_total_floor_mm = round(regional_floor_mm, 1)
    hour_to_regional_floor_ratio = round(ratio, 3)

    gates = {
        "record_hour_mm_ge_75": record_hour_mm >= 75.0,
        "ratio_ge_0_30": hour_to_regional_floor_ratio >= 0.30,
    }
    answer = "passes_pluvial_burst_rule" if all(gates.values()) else "does_not_pass_pluvial_burst_rule"

    primary_gt = {
        "target_family": TARGET_FAMILY,
        "metrics": {
            "record_hour_window_local": "2021-09-01 19:51-20:51",
            "record_hour_mm": record_hour_mm,
            "regional_total_floor_mm": regional_total_floor_mm,
            "hour_to_regional_floor_ratio": hour_to_regional_floor_ratio,
        },
        "gates": gates,
        "answer": answer,
        "rejected_alternative": "slow_routed_river_dominant",
        "computed_consequence": (
            "The record hour supplied about 35% of the regional-total floor, so the New York City phase "
            "fits a short-duration urban pluvial drainage-overload diagnosis."
        ),
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "record_hour_window_local": ["2021-09-01 19:51", "2021-09-01 20:51"],
            "record_hour_inches": record_hour_inches,
            "record_hour_mm_exact": round(record_hour_mm_exact, 3),
            "regional_total_floor_inches": regional_floor_inches,
            "regional_total_floor_mm": regional_total_floor_mm,
            "hour_to_regional_floor_ratio": hour_to_regional_floor_ratio,
            "thresholds": {
                "record_hour_mm": 75.0,
                "hour_to_regional_floor_ratio": 0.30,
            },
        },
        "numeric_tolerances": {
            "record_hour_mm": {"target": record_hour_mm, "tolerance": 0.5},
            "regional_total_floor_mm": {"target": regional_total_floor_mm, "tolerance": 5.0},
            "hour_to_regional_floor_ratio": {"target": hour_to_regional_floor_ratio, "tolerance": 0.02},
        },
        "decision_rules": {
            "record_hour_gate": "record_hour_mm >= 75.0",
            "ratio_gate": "hour_to_regional_floor_ratio >= 0.30",
            "answer": "passes_pluvial_burst_rule if both gates are true; otherwise does_not_pass_pluvial_burst_rule",
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "final_ledger_label",
                    "points": 4,
                    "description": "Returns answer passes_pluvial_burst_rule and target_family rainfall_threshold_ledger.",
                    "partial_credit": "Give 2 points for a correct pluvial-burst label with one missing exact field; give 1 point for a rain-intensity label without the pass result.",
                },
                {
                    "name": "rainfall_anchor_extraction",
                    "points": 4,
                    "description": "Uses the 3.47 inch Central Park record hour, the 2021-09-01 19:51-20:51 local window, and the 10.0 inch regional-total floor.",
                    "partial_credit": "Give 2-3 points for correct values with a missing window or floor wording; give 1 point for using only one anchor.",
                },
                {
                    "name": "conversion_and_ratio_arithmetic",
                    "points": 4,
                    "description": "Computes 88.1 mm, 254.0 mm, and 0.347 with the requested rounding.",
                    "partial_credit": "Give 2-3 points for one rounding or denominator mistake; give 1 point for showing the formulas but not the correct values.",
                },
                {
                    "name": "threshold_gate_logic",
                    "points": 3,
                    "description": "Marks record_hour_mm_ge_75 and ratio_ge_0_30 as true using the specified thresholds.",
                    "partial_credit": "Give 1-2 points for evaluating only one gate correctly or using the right thresholds with one arithmetic slip.",
                },
                {
                    "name": "alternative_rejection_and_interpretation",
                    "points": 3,
                    "description": "Rejects slow_routed_river_dominant because both short-duration gates pass and gives a one-sentence consequence tied to the ledger.",
                    "partial_credit": "Give 1-2 points for a correct pluvial interpretation without the explicit rejection or with a vague consequence.",
                },
                {
                    "name": "compact_json_structure",
                    "points": 2,
                    "description": "Returns the requested six top-level fields without extra narrative.",
                    "partial_credit": "Give 1 point for all substantive content in a less compact structure.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [REPORT_REL_PATH],
            "notes": "Values are parsed from the local WPC Ida rainfall report and rounded according to the visible ledger instructions.",
        },
    }

    out_path = Path(__file__).resolve().parent / "computed_gt.json"
    out_path.write_text(json.dumps(output, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
